import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";import"./chunks/assets.CGKUPeQw.js";var i=JSON.parse(`{"title":"AireGlu Release Notes — 2023","description":"","frontmatter":{},"headers":[],"relativePath":"aireblock-releases/AireGlu/aireglu-2023.md","filePath":"aireblock-releases/AireGlu/aireglu-2023.md","lastUpdated":1786565768000}`),a={name:`aireblock-releases/AireGlu/aireglu-2023.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="aireglu-release-notes-—-2023" tabindex="-1"><span class="fsc-product"><img src="/aireglu-icon.png"> AireGlu Release Notes — 2023</span> <a class="header-anchor" href="#aireglu-release-notes-—-2023" aria-label="Permalink to “AireGlu Release Notes — 2023”">​</a></h1><p>This page contains the AireGlu releases published during 2023.</p><h2 id="version-1-63-0" tabindex="-1">Version 1.63.0 <a class="header-anchor" href="#version-1-63-0" aria-label="Permalink to “Version 1.63.0”">​</a></h2><blockquote><p><strong>Release Date:</strong> December 12, 2023</p></blockquote><h3 id="⚡-improvements" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Allow endpoint versions to be &#39;undeployed&#39; via endpoint list</li></ul><h3 id="🐞-bug-fixes" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix group UI for repository-synced endpoints</li></ul><h3 id="🔧-maintenance" tabindex="-1">🔧 Maintenance <a class="header-anchor" href="#🔧-maintenance" aria-label="Permalink to “🔧 Maintenance”">​</a></h3><ul><li>Upgrade GraphQL for .NET</li><li>Multiple package upgrades</li></ul><h2 id="version-1-62-0" tabindex="-1">Version 1.62.0 <a class="header-anchor" href="#version-1-62-0" aria-label="Permalink to “Version 1.62.0”">​</a></h2><blockquote><p><strong>Release Date:</strong> November 22, 2023</p></blockquote><h3 id="⚡-improvements-1" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-1" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Provide UI guidance on invoking GET endpoints with a body</li></ul><h3 id="🐞-bug-fixes-1" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-1" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Allow invocation of async endpoints from within another endpoint</li><li>Resolve memory leak</li></ul><h2 id="version-1-61-0" tabindex="-1">Version 1.61.0 <a class="header-anchor" href="#version-1-61-0" aria-label="Permalink to “Version 1.61.0”">​</a></h2><blockquote><p><strong>Release Date:</strong> November 14, 2023</p></blockquote><h3 id="⚡-improvements-2" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-2" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Allow grouping of endpoints in the UI</li><li>Support client credentials for invoking endpoints</li></ul><h3 id="🔧-maintenance-1" tabindex="-1">🔧 Maintenance <a class="header-anchor" href="#🔧-maintenance-1" aria-label="Permalink to “🔧 Maintenance”">​</a></h3><ul><li>Multiple package upgrades</li></ul><h2 id="version-1-60-0" tabindex="-1">Version 1.60.0 <a class="header-anchor" href="#version-1-60-0" aria-label="Permalink to “Version 1.60.0”">​</a></h2><blockquote><p><strong>Release Date:</strong> November 1, 2023</p></blockquote><h3 id="🐞-bug-fixes-2" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-2" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Ignore looped references in JSON serialization</li></ul><h2 id="version-1-59-0" tabindex="-1">Version 1.59.0 <a class="header-anchor" href="#version-1-59-0" aria-label="Permalink to “Version 1.59.0”">​</a></h2><blockquote><p><strong>Release Date:</strong> November 1, 2023</p></blockquote><h3 id="⚡-improvements-3" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-3" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Allow debug setting to be controlled locally on repo synced endpoints</li><li>Disallow access to routes based on permissions</li><li>Add time to job schedule start and end dates</li></ul><h3 id="🐞-bug-fixes-3" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-3" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Could see a previously selected endpoint in the editor if current failed to load</li><li>Exception emails to users failed if variable used</li><li>Debug data permissions not applied to Endpoint Errors GraphQL query</li><li>In some scenarios editing JSONPath in an endpoint threw an error</li><li>Liquid mapping was losing timezone information</li></ul><h3 id="🔧-maintenance-2" tabindex="-1">🔧 Maintenance <a class="header-anchor" href="#🔧-maintenance-2" aria-label="Permalink to “🔧 Maintenance”">​</a></h3><ul><li>Move to using custom job scheduler package</li><li>Various package updates</li></ul><h2 id="version-1-58-0" tabindex="-1">Version 1.58.0 <a class="header-anchor" href="#version-1-58-0" aria-label="Permalink to “Version 1.58.0”">​</a></h2><blockquote><p><strong>Release Date:</strong> October 17, 2023</p></blockquote><h3 id="⚡-improvements-4" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-4" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Support stream format type in HTTP request task</li></ul><h3 id="🐞-bug-fixes-4" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-4" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Metrics page was not loading on refresh</li></ul><h3 id="🔧-maintenance-3" tabindex="-1">🔧 Maintenance <a class="header-anchor" href="#🔧-maintenance-3" aria-label="Permalink to “🔧 Maintenance”">​</a></h3><ul><li>Hangfire package upgrades</li></ul><h2 id="version-1-57-0" tabindex="-1">Version 1.57.0 <a class="header-anchor" href="#version-1-57-0" aria-label="Permalink to “Version 1.57.0”">​</a></h2><blockquote><p><strong>Release Date:</strong> October 4, 2023</p></blockquote><h3 id="⚡-improvements-5" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-5" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Add repo information tooltip to repository endpoints</li></ul><h3 id="🐞-bug-fixes-5" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-5" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Sync status on icon should be valid when repo has synced</li></ul><h2 id="version-1-56-0" tabindex="-1">Version 1.56.0 <a class="header-anchor" href="#version-1-56-0" aria-label="Permalink to “Version 1.56.0”">​</a></h2><blockquote><p><strong>Release Date:</strong> October 4, 2023</p></blockquote><h3 id="✨-new-features" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Can use a variable in the endpoint error email input</li><li>When creating a job, you can set it to auto-delete after end date</li><li>Multi-select option on all resource items</li><li>Job edit in ClientV2</li><li>Group field in endpoint editor to support future UI grouping</li><li>Readonly view for endpoints, including repository endpoints</li></ul><h3 id="⚡-improvements-6" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-6" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Sort/search bar redesign</li><li>Role-based menu options</li><li>Input validation for retrievers</li><li>Persist an auto-generated transaction ID throughout endpoint calls when one is not provided</li><li>Allow immediate access to ClientV2 whilst ClientV1 is loading</li><li>Upgrade multi-PDF adapter to guarantee ordering by last modified</li></ul><h3 id="🐞-bug-fixes-6" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-6" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Allow reordering of endpoint tasks containing secrets</li><li>Allow endpoint to create none-algorithm JWT without dummy secret</li><li>Clean up repository retriever logs</li><li>Prevent access to &#39;create&#39; fields once repository created</li></ul><h3 id="⚠️-breaking-changes" tabindex="-1">⚠️ Breaking Changes <a class="header-anchor" href="#⚠️-breaking-changes" aria-label="Permalink to “⚠️ Breaking Changes”">​</a></h3><ul><li>Package upgrades include a breaking change: ensure your <code>JWT_KEY</code> secret is greater than 256 bits</li></ul><h2 id="version-1-55-0" tabindex="-1">Version 1.55.0 <a class="header-anchor" href="#version-1-55-0" aria-label="Permalink to “Version 1.55.0”">​</a></h2><blockquote><p><strong>Release Date:</strong> August 29, 2023</p></blockquote><h3 id="✨-new-features-1" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-1" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Ability to delete expired jobs en masse</li></ul><h3 id="⚡-improvements-7" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-7" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Update to UI button styling</li><li>Separate tab for endpoint input on job and receiver creation</li><li>MESH option disabled if MeshAllowList is empty</li><li>Assign new unique identifier to AireGlu Tasks</li></ul><h3 id="🐞-bug-fixes-7" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-7" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Pressing the reset button on cron builder reset all fields within job creation</li></ul><h3 id="🔧-maintenance-4" tabindex="-1">🔧 Maintenance <a class="header-anchor" href="#🔧-maintenance-4" aria-label="Permalink to “🔧 Maintenance”">​</a></h3><ul><li>Pin Moq Library to 4.18</li></ul><h2 id="version-1-54-0" tabindex="-1">Version 1.54.0 <a class="header-anchor" href="#version-1-54-0" aria-label="Permalink to “Version 1.54.0”">​</a></h2><blockquote><p><strong>Release Date:</strong> July 24, 2023</p></blockquote><h3 id="✨-new-features-2" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-2" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Ability to specify Gov Notify service ID at the tenant level</li><li>Ability to not store input data on endpoint exception</li><li>New UI Receivers list page</li><li>New UI Jobs Page, ability to mass delete expired jobs</li><li>Creating new endpoints will default to having internal authentication</li></ul><h3 id="⚡-improvements-8" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-8" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Max retry limit on failed jobs</li><li>New UI general fixes to loading spinner, icons, and tooltips on disabled endpoint version items</li></ul><h3 id="🐞-bug-fixes-8" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-8" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Inputs on GET endpoints when invoking through the &#39;test/try it out&#39; page were ignored</li></ul><h3 id="🔧-maintenance-5" tabindex="-1">🔧 Maintenance <a class="header-anchor" href="#🔧-maintenance-5" aria-label="Permalink to “🔧 Maintenance”">​</a></h3><ul><li>Multiple package upgrades</li></ul><h2 id="version-1-53-0" tabindex="-1">Version 1.53.0 <a class="header-anchor" href="#version-1-53-0" aria-label="Permalink to “Version 1.53.0”">​</a></h2><blockquote><p><strong>Release Date:</strong> July 6, 2023</p></blockquote><h3 id="✨-new-features-3" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-3" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Ability to toggle automatic sync and edit error email for Repositories</li></ul><h3 id="🐞-bug-fixes-9" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-9" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix more actions menu placement</li></ul><h3 id="🔧-maintenance-6" tabindex="-1">🔧 Maintenance <a class="header-anchor" href="#🔧-maintenance-6" aria-label="Permalink to “🔧 Maintenance”">​</a></h3><ul><li>Multiple package upgrades</li></ul><h2 id="version-1-52-0" tabindex="-1">Version 1.52.0 <a class="header-anchor" href="#version-1-52-0" aria-label="Permalink to “Version 1.52.0”">​</a></h2><blockquote><p><strong>Release Date:</strong> June 21, 2023</p></blockquote><h3 id="✨-new-features-4" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-4" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>New Repositories UI</li><li>Jobs UI date improvements</li><li>Upgrade to .NET 7</li></ul><h3 id="🐞-bug-fixes-10" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-10" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixes to iframe issues in new UI</li><li>Improve error message for users not authorised for repository sync</li></ul><h3 id="🔒-security" tabindex="-1">🔒 Security <a class="header-anchor" href="#🔒-security" aria-label="Permalink to “🔒 Security”">​</a></h3><ul><li>Various package upgrades</li></ul><h2 id="version-1-51-0" tabindex="-1">Version 1.51.0 <a class="header-anchor" href="#version-1-51-0" aria-label="Permalink to “Version 1.51.0”">​</a></h2><blockquote><p><strong>Release Date:</strong> June 7, 2023</p></blockquote><h3 id="✨-new-features-5" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-5" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>New UI performance improvements</li><li>New UI Jobs and Repository Retrieval Editor updates</li></ul><h3 id="🐞-bug-fixes-11" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-11" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Displaying of &#39;Last run&#39;/&#39;Next run&#39; in the New UI Jobs page</li><li>Repository retrieval removal of auto retry, retrying will be based on the schedule</li></ul><h3 id="🔒-security-1" tabindex="-1">🔒 Security <a class="header-anchor" href="#🔒-security-1" aria-label="Permalink to “🔒 Security”">​</a></h3><ul><li>Various package upgrades</li></ul><h2 id="version-1-50-0" tabindex="-1">Version 1.50.0 <a class="header-anchor" href="#version-1-50-0" aria-label="Permalink to “Version 1.50.0”">​</a></h2><blockquote><p><strong>Release Date:</strong> May 24, 2023</p></blockquote><h3 id="✨-new-features-6" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-6" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Send error emails on non-exception errors</li></ul><h3 id="🐞-bug-fixes-12" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-12" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix deletion of transaction data on debug toggle off</li><li>Enable use of variables and secrets in git backed endpoints for JWT and HTTP request tasks</li></ul><h2 id="version-1-49-0" tabindex="-1">Version 1.49.0 <a class="header-anchor" href="#version-1-49-0" aria-label="Permalink to “Version 1.49.0”">​</a></h2><blockquote><p><strong>Release Date:</strong> May 11, 2023</p></blockquote><h3 id="✨-new-features-7" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-7" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Logging improvements</li><li>Update icon for repository endpoints</li><li>Simplify batch message processing deployment</li></ul><h3 id="🐞-bug-fixes-13" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-13" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Improve description for error message on missing variables</li><li>Forgot password issues</li><li>Password corrupted in HTTP request task on endpoint edit</li></ul><h2 id="version-1-48-0" tabindex="-1">Version 1.48.0 <a class="header-anchor" href="#version-1-48-0" aria-label="Permalink to “Version 1.48.0”">​</a></h2><blockquote><p><strong>Release Date:</strong> April 20, 2023</p></blockquote><h3 id="🚑-hotfixes" tabindex="-1">🚑 Hotfixes <a class="header-anchor" href="#🚑-hotfixes" aria-label="Permalink to “🚑 Hotfixes”">​</a></h3><ul><li>Revert Mongo driver upgrade due to compatibility issue with Mongo 4.2.24</li></ul><h2 id="version-1-47-0" tabindex="-1">Version 1.47.0 <a class="header-anchor" href="#version-1-47-0" aria-label="Permalink to “Version 1.47.0”">​</a></h2><blockquote><p><strong>Release Date:</strong> April 19, 2023</p></blockquote><h3 id="✨-new-features-8" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-8" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Optimise batch message processing</li><li>Update endpoint import/export icons</li><li>By default show active jobs only</li></ul><h3 id="🐞-bug-fixes-14" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-14" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Ensure global logout on multiple tabs for RBAC users</li></ul><h3 id="🔧-maintenance-7" tabindex="-1">🔧 Maintenance <a class="header-anchor" href="#🔧-maintenance-7" aria-label="Permalink to “🔧 Maintenance”">​</a></h3><ul><li>Upgrade Mongo driver to 2.19.1</li></ul><h2 id="version-1-46-0" tabindex="-1">Version 1.46.0 <a class="header-anchor" href="#version-1-46-0" aria-label="Permalink to “Version 1.46.0”">​</a></h2><blockquote><p><strong>Release Date:</strong> April 5, 2023</p></blockquote><h3 id="✨-new-features-9" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-9" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Link to public AireGlu docs in UI</li></ul><h3 id="🐞-bug-fixes-15" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-15" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Error emails not sending on endpoint exception</li></ul><h2 id="version-1-45-0" tabindex="-1">Version 1.45.0 <a class="header-anchor" href="#version-1-45-0" aria-label="Permalink to “Version 1.45.0”">​</a></h2><blockquote><p><strong>Release Date:</strong> April 3, 2023</p></blockquote><h3 id="✨-new-features-10" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-10" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Return URL for endpoint on endpoints overview API</li><li>Allow <code>PRIVATE_ASYNC_RUNTIME_HOST</code> variable to be unset on async deployments</li></ul><h3 id="🐞-bug-fixes-16" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-16" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix endpoint editing undeploying other version</li><li>Fix Insights tab loading issues</li><li>Fix Insights tab graphs</li></ul><h2 id="version-1-44-0" tabindex="-1">Version 1.44.0 <a class="header-anchor" href="#version-1-44-0" aria-label="Permalink to “Version 1.44.0”">​</a></h2><blockquote><p><strong>Release Date:</strong> April 3, 2023</p></blockquote><h3 id="✨-new-features-11" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-11" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Allow numbers in endpoint names</li><li>Add HS256 algorithm for JWT generation</li></ul><h2 id="version-1-43-0" tabindex="-1">Version 1.43.0 <a class="header-anchor" href="#version-1-43-0" aria-label="Permalink to “Version 1.43.0”">​</a></h2><blockquote><p><strong>Release Date:</strong> March 22, 2023</p></blockquote><h3 id="✨-new-features-12" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-12" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added dead letter queues</li><li>Display tenant in nav bar</li></ul><h3 id="⚡-improvements-9" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-9" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Downstream endpoint calls from async endpoint invocation should pass through to async runtime</li></ul><h3 id="🐞-bug-fixes-17" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-17" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix Insights tab issues</li></ul><h2 id="version-1-42-0" tabindex="-1">Version 1.42.0 <a class="header-anchor" href="#version-1-42-0" aria-label="Permalink to “Version 1.42.0”">​</a></h2><blockquote><p><strong>Release Date:</strong> March 7, 2023</p></blockquote><h3 id="⚡-improvements-10" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-10" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Restart runtime and job runner as sync if async functionality fails on startup</li><li>Improve structure of runtime logs</li></ul><h3 id="🐞-bug-fixes-18" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-18" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix HL7 FHIR option on input dropdown in endpoint wizard</li><li>Fix log out of new UI - invalidation of tenant profile</li></ul><h2 id="version-1-41-0" tabindex="-1">Version 1.41.0 <a class="header-anchor" href="#version-1-41-0" aria-label="Permalink to “Version 1.41.0”">​</a></h2><blockquote><p><strong>Release Date:</strong> March 7, 2023</p></blockquote><h3 id="⚡-improvements-11" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-11" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Rename <code>DIRECT_RUNTIME_HOST</code> to <code>PRIVATE_RUNTIME_HOST</code></li></ul><h3 id="🐞-bug-fixes-19" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-19" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fix batch functionality to work with repository endpoints</li></ul><h3 id="🔧-maintenance-8" tabindex="-1">🔧 Maintenance <a class="header-anchor" href="#🔧-maintenance-8" aria-label="Permalink to “🔧 Maintenance”">​</a></h3><ul><li>Upgrade Mongo DB drivers to v6</li><li>Upgrade message broker client to 0.2.0-alpha0058</li></ul><h2 id="version-1-40-0" tabindex="-1">Version 1.40.0 <a class="header-anchor" href="#version-1-40-0" aria-label="Permalink to “Version 1.40.0”">​</a></h2><blockquote><p><strong>Release Date:</strong> February 20, 2023</p></blockquote><h3 id="✨-new-features-13" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-13" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Email task change - Addition of Bcc</li><li>JWT task change - Addition of None algorithm and ability to set header type as JSON</li><li>Async - Passing through of transaction ID to callback input</li></ul><h3 id="🐞-bug-fixes-20" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-20" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>New UI - iframes fixed when used with RBAC</li></ul><h3 id="🔧-maintenance-9" tabindex="-1">🔧 Maintenance <a class="header-anchor" href="#🔧-maintenance-9" aria-label="Permalink to “🔧 Maintenance”">​</a></h3><ul><li>Upgrade MultiPDF adapter - 1.0.0-CI-20230203-131339</li></ul><h2 id="version-1-39-0" tabindex="-1">Version 1.39.0 <a class="header-anchor" href="#version-1-39-0" aria-label="Permalink to “Version 1.39.0”">​</a></h2><blockquote><p><strong>Release Date:</strong> February 6, 2023</p></blockquote><h3 id="⚡-improvements-12" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-12" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improvements to error logging</li></ul><h3 id="🐞-bug-fixes-21" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-21" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>InternalAuth fixes - MESH receiver not able to invoke endpoints with InternalOnly set</li><li>InternalAuth fixes - Repository-backed endpoints not able to invoke other repository endpoints with InternalOnly set</li><li>New UI fixes</li></ul>`,178)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};